{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configuration, which could allow unintended public access."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, which makes it difficult to track access and detect potential unauthorized access."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket does not explicitly block public ACLs, which could lead to unintended public access if ACLs are misconfigured."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
  }, {})

  lifecycle_rule {
    enabled = true
    expiration {
      days = 365
    }
  }
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket                  = aws_s3_bucket.data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "data" {
  bucket        = aws_s3_bucket.data.id
  target_bucket = "${local.resource_prefix.value}-logs"
  target_prefix = "${local.resource_prefix.value}/"
}",
  "fix_summary": "Added a public access block to prevent unintended public access, enabled access logging for observability, and added lifecycle rules to manage object expiration."
}
